script:
country_event = {
	id = crisis.2000
	hide_window = yes
	is_test_event = yes

	trigger = {
		always = no
	}

	immediate = {
		set_global_flag = ai_invasion_happened
		set_global_flag = ai_ghost_signal
		set_global_flag = galactic_crisis_happened
		# The Arrival
		every_country = {
			limit = {
				OR = {
					is_country_type = default
					is_country_type = fallen_empire
					is_country_type = awakened_fallen_empire
				}
			}
			country_event = { id = crisis.2022 }
		}
		# First Machine World
		if = {
			limit = {
				any_galaxy_planet = { has_carrier_flag = machine_world_1 }
			}
			random_galaxy_planet = {
				limit = { has_carrier_flag = machine_world_1 }
				carrier_event = { id = crisis.2025 days = 20 random = 10 }
			}
		}
		else_if = {
			random_galaxy_planet = {
				limit = { is_planet_class = pc_barren }
				carrier_event = { id = crisis.2025 days = 20 random = 10 }
			}
		}
		# Second Machine World
		if = {
			limit = {
				any_galaxy_planet = { has_carrier_flag = machine_world_2 }
			}
			random_galaxy_planet = {
				limit = { has_carrier_flag = machine_world_2 }
				carrier_event = { id = crisis.2026 days = 40 random = 10 }
			}
		}
		else_if = {
			random_galaxy_planet = {
				limit = { is_planet_class = pc_molten }
				carrier_event = { id = crisis.2026 days = 40 random = 10 }
			}
		}
		# Third Machine World
		if = {
			limit = {
				any_galaxy_planet = { has_carrier_flag = machine_world_3 }
			}
			random_galaxy_planet = {
				limit = { has_carrier_flag = machine_world_3 }
				carrier_event = { id = crisis.2027 days = 60 random = 10 }
			}
		}
		else_if = {
			random_galaxy_planet = {
				limit = { is_planet_class = pc_gas_giant }
				carrier_event = { id = crisis.2027 days = 60 random = 10 }
			}
		}
		# Fourth Machine World
		if = {
			limit = {
				any_galaxy_planet = { has_carrier_flag = machine_world_4 }
			}
			random_galaxy_planet = {
				limit = { has_carrier_flag = machine_world_4 }
				carrier_event = { id = crisis.2028 days = 80 random = 10 }
			}
		}
		else_if = {
			random_galaxy_planet = {
				limit = { is_planet_class = pc_toxic }
				carrier_event = { id = crisis.2028 days = 80 random = 10 }
			}
		}
		# Synth Infiltration
		every_country = {
			limit = { is_country_type = default }
			if = {
				limit = {
					owner_species = { is_psionic_species = no }
					NOR = {
						is_hive_empire = yes
						is_machine_empire = yes
						is_individual_machine = yes
					}
				}
				country_event = { id = crisis.2085 days = 260 random = 20 }
			}
			if = {
				limit = { is_hive_empire = yes }
				country_event = { id = crisis.2086 days = 260 random = 20 }
			}
			if = {
				limit = { owner_species = { is_psionic_species = yes } }
				country_event = { id = crisis.2087 days = 260 random = 20 }
			}
			if = {
				limit = {
					OR = {
						is_machine_empire = yes
						is_individual_machine = yes
					}
				}
				country_event = { id = crisis.2313 days = 260 random = 20 }
			}
		}
	}
}

