					is_same_species = event_target:custodian_bot
				}
			}
			kill_all_pop = yes
		}
		create_army = {
			owner = event_target:contingency
			type = "robotic_defense_army"
		}
		create_army = {
			owner = event_target:contingency
			type = "robotic_defense_army"
		}
		create_army = {
