		}
		create_army = {
			owner = event_target:contingency
			type = "robotic_defense_army"
		}
		every_country = {
			limit = { has_event_chain = "ai_crisis_chain" }
			add_event_chain_counter = {
				event_chain = "ai_crisis_chain"
				counter = "assimilated_worlds"
				amount = 1
			}
		}

		solar_system = {
			if = { # Build starbase if no other colonies are left and no hostile fleet is in the system
				limit = {
					NOR = {
						exists = starbase
						any_system_planet = {
							has_owner = yes
							owner = {
								NOT = { is_same_value = event_target:contingency }
							}
						}
						any_fleet_in_system = {
							owner = { is_hostile = event_target:contingency }
						}
					}
				}
				create_starbase = {
					size = starbase_ai
					owner = event_target:contingency
				}
				if = {
					limit = {
						NOT = {
							any_system_ambient_object = { has_ambient_object_flag = contingency_system_effect }
						}
					}
					star = {
						create_ambient_object = {
							type = "contingency_1"
							location = this
						}
						last_created_ambient_object = {
							set_ambient_object_flag = contingency_system_effect
							set_location = {
								target = prev
								distance = 0
								angle = random
							}
						}
					}
				}
			}
		}
	}
}

